SELECT id, title, applicant_text, investigator, status
FROM cases
WHERE id IN (SELECT case_id FROM doc_registry WHERE year = 2015 AND reg_no BETWEEN 4470 AND 4472);

SELECT id, title, opened_at, applicant_text, investigator, status, status_at
FROM cases
WHERE id = (SELECT case_id FROM doc_registry WHERE year = 2015 AND reg_no = 3311);

SELECT id, full_name, patronymic, father_id
FROM persons
WHERE id = 4127 OR id = (SELECT father_id FROM persons WHERE id = 4127);

SELECT id, full_name, prev_last_name
FROM persons
WHERE id = (SELECT mother_id FROM persons WHERE id = 4127);
